"use strict";(globalThis.webpackChunkwebsite||=[]).push([[12559],{40057(o){o.exports=JSON.parse('{"tag":{"label":"\u65b9\u6cd5\u8bba","permalink":"/docs/tags/\u65b9\u6cd5\u8bba","allTagsPath":"/docs/tags","count":12,"items":[{"id":"selfdevelop/outlook/society/yantielun","title":"\u300a\u76d0\u94c1\u8bba\u300b\uff1a\u56db\u5c42\u903b\u8f91\u3001\u516b\u6761\u5224\u65ad\u4e0e\u4e94\u95ee\u6d41\u7a0b","description":"\u4ece\u300a\u76d0\u94c1\u8bba\u300b\u90a3\u573a\u5173\u4e8e\u5b98\u5e9c\u8be5\u4e0d\u8be5\u4e0b\u573a\u8d5a\u94b1\u7684\u8fa9\u8bba\u91cc\uff0c\u63d0\u70bc\u51fa\u56db\u5c42\u903b\u8f91\u3001\u516b\u6761\u5224\u65ad\u4e0e\u4e00\u5957\u4e94\u95ee\u6d41\u7a0b\uff0c\u914d\u4e0a\u5de5\u4f5c\u3001\u6210\u957f\u4e0e\u751f\u6d3b\u7684\u5177\u4f53\u573a\u666f\u548c\u4e00\u4e2a\u8d70\u5b8c\u6574\u6d41\u7a0b\u7684\u4f8b\u5b50\uff0c\u7528\u6765\u62c6\u5f00\u65e5\u5e38\u73b0\u8c61\u3001\u628a\u94b1\u7684\u4e8b\u8bf4\u5b8c\u6574\u3002","permalink":"/docs/selfdevelop/outlook/society/yantielun"},{"id":"selfdevelop/ability/ai/index","title":"AI \u4f7f\u7528\u80fd\u529b","description":"\u666e\u901a\u4eba\uff08\u975e\u6280\u672f\u4ece\u4e1a\u8005\uff09\u5b66\u4e60\u548c\u4f7f\u7528 AI \u7684\u65b9\u6cd5\u8bba\u603b\u89c8\uff1a\u4e24\u4efd\u5b66\u4e60\u89c4\u5212\uff08\u96f6\u57fa\u7840\u5165\u95e8\u7248\u3001\u4e00\u4eba\u516c\u53f8 AI Agent \u8fdb\u9636\u7248\uff09\u4e0e\u8fdb\u9636\u7248\u914d\u5957\u7684\u516d\u9636\u6bb5\u5b66\u4e60\u6750\u6599\uff0c\u542b\u5168\u6d41\u7a0b\u5de5\u5177\u9009\u578b\u603b\u8868\u3001\u6bcf\u5468\u65f6\u957f\u8282\u594f\u3001\u80fd\u529b\u81ea\u8bc4\u8868\u4e0e\u6bcf\u9636\u6bb5\u7edf\u4e00\u7684\u8fdb\u5165\u68c0\u67e5\u4e0e\u8d44\u4ea7\u4ea4\u63a5\u673a\u5236\u3002","permalink":"/docs/selfdevelop/ability/ai/"},{"id":"selfdevelop/ability/ai/ai-collaboration-methodology","title":"AI \u534f\u4f5c\u65b9\u6cd5\u8bba\uff1a\u951a\u70b9\u5faa\u73af\u4e0e\u4e94\u4ef6\u5957\u5de5\u5177\u7bb1","description":"\u4e00\u5957\u4e0e AI \u957f\u671f\u534f\u4f5c\u7684\u5b8c\u6574\u65b9\u6cd5\uff1a\u628a\\"\u4eba\u673a\u534f\u4f5c\\"\u91cd\u65b0\u5b9a\u4e49\u4e3a\u98ce\u9669\u63a7\u5236\u95ee\u9898\uff0c\u7528\u8ba4\u77e5\u951a\u70b9\uff08\u5168\u91cf + \u589e\u91cf\uff09\u56fa\u5b9a\u4fe1\u606f\u3001\u7528\u4e94\u6b65\u951a\u70b9\u5faa\u73af\uff08\u7acb\u951a\u2014\u5171\u521b\u2014\u6267\u884c\u2014\u6821\u6838\u2014\u5f52\u96c6\uff09\u56fa\u5b9a\u8fc7\u7a0b\u3001\u7528\u4e09\u6761\u8f66\u9053\u63a7\u5236\u6210\u672c\uff0c\u5e76\u7ed9\u51fa\u53ef\u76f4\u63a5\u6284\u8d70\u7684\u4e94\u4ef6\u5957\u5de5\u5177\u7bb1\uff08\u9879\u76ee\u624b\u518c\u3001\u53d8\u66f4\u5361\u3001\u8bc4\u5ba1\u5355\u3001\u51b3\u7b56\u65e5\u5fd7\u3001\u89d2\u8272\u5361\uff09\u3001\u56db\u4e2a\u5ea6\u91cf\u6307\u6807\u4e0e\u4e94\u4e2a\u5e38\u89c1\u5751\uff0c\u542b\u8de8\u9886\u57df\u8fc1\u79fb\u5bf9\u7167\u8868\u4e0e\u4e00\u9875\u901f\u67e5\u3002","permalink":"/docs/selfdevelop/ability/ai/ai-collaboration-methodology"},{"id":"selfdevelop/outlook/maothought/overview","title":"\u4f53\u7cfb\u5730\u56fe\uff1a\u4e00\u6761\u4e3b\u7ebf\u4e0e\u4e09\u4e2a\u57fa\u672c\u65b9\u9762","description":"\u6bdb\u6cfd\u4e1c\u601d\u60f3\u4e0d\u662f\u4e00\u5806\u65b9\u6cd5\u7684\u5408\u96c6\uff0c\u800c\u662f\u4e00\u5f20\u6709\u4f9d\u8d56\u5173\u7cfb\u7684\u56fe\u3002\u672c\u6587\u7ed9\u51fa\u4e09\u4e2a\u57fa\u672c\u65b9\u9762\uff08\u5b9e\u4e8b\u6c42\u662f\u3001\u7fa4\u4f17\u8def\u7ebf\u3001\u72ec\u7acb\u81ea\u4e3b\uff09\u5404\u81ea\u56de\u7b54\u4ec0\u4e48\u95ee\u9898\u3001\u5982\u4f55\u4e92\u76f8\u652f\u6491\uff0c\u4ee5\u53ca\u8c03\u67e5\u7814\u7a76\u3001\u77db\u76fe\u5206\u6790\u3001\u6218\u7565\u6218\u672f\u3001\u7edf\u4e00\u6218\u7ebf\u3001\u7fa4\u4f17\u52a8\u5458\u3001\u5b9e\u8df5\u68c0\u9a8c\u5728\u4f53\u7cfb\u4e2d\u7684\u4f4d\u7f6e\u4e0e\u5f62\u6210\u8109\u7edc\u3002","permalink":"/docs/selfdevelop/outlook/maothought/overview"},{"id":"selfdevelop/outlook/maothought/united-front","title":"\u5206\u6e05\u654c\u53cb\uff1a\u53c8\u8054\u5408\u53c8\u6597\u4e89\u7684\u5206\u5bf8","description":"\u4ece\u300a\u4e2d\u56fd\u793e\u4f1a\u5404\u9636\u7ea7\u7684\u5206\u6790\u300b\u4e0e\u6297\u65e5\u6c11\u65cf\u7edf\u4e00\u6218\u7ebf\u7684\u7b56\u7565\u51fa\u53d1\uff0c\u8bb2\u6e05\u6309\u5904\u5883\u800c\u975e\u6001\u5ea6\u5206\u7c7b\u7684\u65b9\u6cd5\u3001\u4e94\u4e2a\u9636\u7ea7\u4e0e\u653f\u6cbb\u5f52\u7c7b\u7684\u533a\u522b\u3001\\"\u6709\u7406\u6709\u5229\u6709\u8282\\"\u4e09\u539f\u5219\u7684\u7cbe\u786e\u5206\u5bf8\uff0c\u4e3a\u4f55\u53ea\u8054\u5408\u4e0e\u53ea\u6597\u4e89\u90fd\u4f1a\u5931\u8d25\uff0c\u5e76\u660e\u786e\u8fd9\u5957\u6846\u67b6\u7684\u9002\u7528\u8303\u56f4\u4e0e\u4e09\u5904\u7981\u7528\u573a\u666f\u3002","permalink":"/docs/selfdevelop/outlook/maothought/united-front"},{"id":"selfdevelop/outlook/maothought/practice-and-cognition","title":"\u5b9e\u8df5\u4e0e\u8ba4\u8bc6\uff1a\u4e24\u6b21\u98de\u8dc3\u4e0e\u77e5\u884c\u95ed\u73af","description":"\u4ece\u300a\u5b9e\u8df5\u8bba\u300b\u51fa\u53d1\uff0c\u8bb2\u6e05\u611f\u6027\u8ba4\u8bc6\u5982\u4f55\u4e0a\u5347\u4e3a\u7406\u6027\u8ba4\u8bc6\u3001\u7406\u6027\u8ba4\u8bc6\u53c8\u5982\u4f55\u56de\u5230\u5b9e\u8df5\u53d7\u68c0\uff0c\u6307\u51fa\u7edd\u5927\u591a\u6570\u4eba\u5361\u5728\u7b2c\u4e00\u6b21\u98de\u8dc3\u6216\u8df3\u8fc7\u7b2c\u4e8c\u6b21\u98de\u8dc3\uff0c\u5e76\u7ed9\u51fa\u5224\u65ad\u65e5\u5fd7\u3001\u6700\u5c0f\u53ef\u9a8c\u8bc1\u52a8\u4f5c\u4e0e\u590d\u76d8\u5206\u53c9\u70b9\u4e09\u5957\u53ef\u6267\u884c\u65b9\u6cd5\u3002","permalink":"/docs/selfdevelop/outlook/maothought/practice-and-cognition"},{"id":"selfdevelop/outlook/maothought/casebook","title":"\u6848\u4f8b\u89e3\u5256\u5ba4\uff1a\u4e94\u4e2a\u6848\u4f8b\u7684\u4e94\u6bb5\u62c6\u6cd5","description":"\u7528\u540c\u4e00\u5957\u4e94\u6bb5\u62c6\u6cd5\uff08\u73b0\u8c61\u3001\u6761\u4ef6\u3001\u65b9\u6cd5\u3001\u4eca\u5929\u7684\u7b49\u4ef7\u7ed3\u6784\u3001\u5931\u6548\u8fb9\u754c\uff09\u89e3\u5256\u901a\u9053\u8f6c\u5175\u3001\u6297\u65e5\u6c11\u65cf\u7edf\u4e00\u6218\u7ebf\u7684\u7b56\u7565\u8c03\u6574\u3001\u4e09\u5927\u6218\u5f79\u7684\u5175\u529b\u96c6\u4e2d\u3001\u4e24\u5f39\u4e00\u661f\u7684\u7ec4\u7ec7\u65b9\u5f0f\u4e0e\u8131\u8d2b\u653b\u575a\u7684\u5efa\u6863\u7acb\u5361\uff0c\u53e6\u8bbe\u4e00\u8282\u8bf4\u660e\\"\u672a\u88ab\u9009\u4e2d\u7684\u6837\u672c\\"\uff0c\u5e76\u5728\u6700\u540e\u7ed9\u51fa\u4e94\u4e2a\u6848\u4f8b\u7684\u6a2a\u5411\u5bf9\u7167\u3002","permalink":"/docs/selfdevelop/outlook/maothought/casebook"},{"id":"selfdevelop/outlook/maothought/index","title":"\u6bdb\u6cfd\u4e1c\u601d\u60f3\uff1a\u4e00\u5957\u5224\u65ad\u95ee\u9898\u7684\u987a\u5e8f","description":"\u628a\u300a\u6bdb\u6cfd\u4e1c\u9009\u96c6\u300b\u91cc\u6563\u843d\u5404\u7bc7\u7684\u601d\u60f3\u65b9\u6cd5\u6574\u7406\u6210\u4e00\u5957\u4e92\u76f8\u54ac\u5408\u7684\u4f53\u7cfb\uff0c\u914d\u5386\u53f2\u4e0e\u73b0\u5b9e\u6848\u4f8b\u7684\u89e3\u5256\uff0c\u5e76\u8f6c\u8bd1\u6210\u666e\u901a\u4eba\u5728\u5de5\u4f5c\u4e0e\u751f\u6d3b\u4e2d\u80fd\u7528\u7684\u539f\u5219\u3001\u65b9\u6cd5\u4e0e\u53cd\u6a21\u5f0f\u3002\u9644\u5341\u7bc7\u6b63\u6587\u7684\u9605\u8bfb\u8def\u7ebf\u3002","permalink":"/docs/selfdevelop/outlook/maothought/"},{"id":"selfdevelop/outlook/maothought/mass-line","title":"\u7fa4\u4f17\u8def\u7ebf\uff1a\u4ece\u7fa4\u4f17\u4e2d\u6765\uff0c\u5230\u7fa4\u4f17\u4e2d\u53bb","description":"\u628a\u7fa4\u4f17\u8def\u7ebf\u8bfb\u6210\u4e00\u5957\u52a8\u5458\u4e0e\u53cd\u9988\u7684\u6280\u672f\u800c\u975e\u9053\u5fb7\u53e3\u53f7\uff1a\u96c6\u4e2d\u4e0e\u8fd4\u8fd8\u7684\u5b8c\u6574\u5faa\u73af\u3001\u4e00\u822c\u53f7\u53ec\u4e0e\u4e2a\u522b\u6307\u5bfc\u7684\u7ed3\u5408\u3001\u300a\u515a\u59d4\u4f1a\u7684\u5de5\u4f5c\u65b9\u6cd5\u300b\u91cc\u516d\u6761\u53ef\u8fc1\u79fb\u7684\u9886\u5bfc\u6280\u672f\uff0c\u4ee5\u53ca\u628a\\"\u7fa4\u4f17\\"\u62bd\u8c61\u5316\u3001\u628a\u6700\u54cd\u7684\u58f0\u97f3\u5f53\u6c11\u610f\u7b49\u4e94\u79cd\u5931\u6548\u65b9\u5f0f\u3002","permalink":"/docs/selfdevelop/outlook/maothought/mass-line"},{"id":"selfdevelop/outlook/maothought/self-discipline","title":"\u81ea\u6211\u8981\u6c42\uff1a\u53cd\u5bf9\u81ea\u7531\u4e3b\u4e49\u4e0e\u6279\u8bc4\u7684\u673a\u5236","description":"\u628a\u300a\u53cd\u5bf9\u81ea\u7531\u4e3b\u4e49\u300b\u91cc\u6700\u5e38\u89c1\u7684\u516b\u79cd\u8868\u73b0\u8bfb\u6210\u4e00\u4efd\u81ea\u6211\u7ba1\u7406\u7684\u75c5\u7076\u6e05\u5355\uff0c\u8bb2\u6e05\u6279\u8bc4\u4e0e\u81ea\u6211\u6279\u8bc4\u4e3a\u4ec0\u4e48\u5fc5\u987b\u88ab\u8bbe\u8ba1\u6210\u673a\u5236\u800c\u4e0d\u662f\u7f8e\u5fb7\uff0c\u8bf4\u660e\\"\u653e\u4e0b\u5305\u88b1\uff0c\u5f00\u52a8\u673a\u5668\\"\u8981\u653e\u4e0b\u7684\u5230\u5e95\u662f\u4ec0\u4e48\uff0c\u5e76\u91cd\u7b14\u6807\u51fa\u81ea\u6211\u6279\u8bc4\u6ed1\u5411\u81ea\u6211\u653b\u51fb\u7684\u5224\u522b\u6cd5\u4e0e\u505c\u6b62\u89c4\u5219\u3002","permalink":"/docs/selfdevelop/outlook/maothought/self-discipline"},{"id":"selfdevelop/outlook/maothought/principles","title":"\u843d\u5730\u603b\u7eb2\uff1a\u5341\u56db\u6761\u539f\u5219\u3001\u4e94\u7c7b\u573a\u666f\u4e0e\u516d\u79cd\u53cd\u6a21\u5f0f","description":"\u628a\u524d\u9762\u4e5d\u7bc7\u6536\u6210\u4e00\u4efd\u53ef\u4ee5\u76f4\u63a5\u7528\u7684\u6e05\u5355\uff1a\u5341\u56db\u6761\u539f\u5219\u5404\u81ea\u4f9d\u636e\u54ea\u6761\u65b9\u6cd5\u4e0e\u5bf9\u5e94\u52a8\u4f5c\u3001\u5de5\u4f5c\u5b66\u4e60\u53d7\u632b\u5173\u7cfb\u4e94\u7c7b\u573a\u666f\u7684\u6700\u5c0f\u52a8\u4f5c\u4e0e\u964d\u7ea7\u65b9\u6848\u3001\u516d\u79cd\u628a\u65b9\u6cd5\u7528\u6b6a\u7684\u5178\u578b\uff0c\u4ee5\u53ca\u4e00\u9875\u7eb8\u7684\u4e0a\u624b\u987a\u5e8f\u4e0e\u4e09\u4e2a\u6bcf\u5468\u52a8\u4f5c\u3002","permalink":"/docs/selfdevelop/outlook/maothought/principles"},{"id":"selfdevelop/outlook/maothought/investigation","title":"\u8c03\u67e5\u7814\u7a76\uff1a\u6ca1\u6709\u8c03\u67e5\u5c31\u6ca1\u6709\u53d1\u8a00\u6743","description":"\u4ece\u300a\u53cd\u5bf9\u672c\u672c\u4e3b\u4e49\u300b\u4e0e\u300a\u519c\u6751\u8c03\u67e5\u300b\u7684\u5e8f\u8a00\u51fa\u53d1\uff0c\u8bb2\u6e05\\"\u7528\u60f3\u51fa\u6765\u7684\u4e1c\u897f\u4ee3\u66ff\u67e5\u51fa\u6765\u7684\u4e1c\u897f\\"\u4e3a\u4ec0\u4e48\u662f\u6700\u8d35\u7684\u9519\u8bef\uff0c\u7ed9\u51fa\u773c\u775b\u5411\u4e0b\u3001\u5f00\u8c03\u67e5\u4f1a\u3001\u89e3\u5256\u4e00\u53ea\u9ebb\u96c0\u4e09\u9879\u6280\u672f\u4e0e\u4e00\u4efd\u56db\u95ee\u6e05\u5355\uff0c\u5e76\u6307\u51fa\u8c03\u67e5\u53d8\u6210\u627e\u8bc1\u636e\u3001\u53d8\u6210\u5835\u4eba\u5634\u7b49\u4e94\u79cd\u5931\u6548\u65b9\u5f0f\u3002","permalink":"/docs/selfdevelop/outlook/maothought/investigation"}],"unlisted":false}}')}}]);